//! Behavioural tests pinned to the observed output of the C++ reference binary
//! (`/workspace/dataset/test11_executable`). Every expectation here was produced
//! by running that binary, not by reasoning about what IDNA "should" do — the
//! C++ library is a set of stubs and this port reproduces the stubs exactly.

use idna_rs::idna;

/// The five examples documented in the header comment of `test11.cpp`.
#[test]
fn documented_examples() {
    let cases: [(&str, &str); 5] = [
        ("example.com", "xn--example.com example.com xn--example.com example.com 1 1 1 0 example.com example.com 2"),
        ("test.example.com", "xn--test.example.com test.example.com xn--test.example.com test.example.com 1 1 1 0 test.example.com test.example.com 3"),
        ("localhost", "xn--localhost localhost xn--localhost localhost 1 1 1 0 localhost localhost 1"),
        ("日本語.jp", "xn--日本語.jp 日本語.jp xn--日本語.jp 日本語.jp 1 1 0 1 日本語.jp 日本語.jp 2"),
        ("中国.cn", "xn--中国.cn 中国.cn xn--中国.cn 中国.cn 1 1 0 1 中国.cn 中国.cn 2"),
    ];
    for (input, expected) in cases {
        assert_eq!(render(input.as_bytes()), expected, "input {input:?}");
    }
}

/// The built-in inputs used when no arguments are supplied.
#[test]
fn default_inputs() {
    assert_eq!(render(b"one"), "xn--one one xn--one one 1 1 1 0 one one 1");
    assert_eq!(
        render(b"two.three"),
        "xn--two.three two.three xn--two.three two.three 1 1 1 0 two.three two.three 2"
    );
    assert_eq!(
        render(b"four.five.six"),
        "xn--four.five.six four.five.six xn--four.five.six four.five.six 1 1 1 0 four.five.six four.five.six 3"
    );
}

/// An empty argument still produces a full line, with two empty fields in a row.
#[test]
fn empty_input() {
    assert_eq!(render(b""), "xn--  xn--  0 0 1 0   1");
}

#[test]
fn to_ascii_prefixes_unconditionally_and_folds_case() {
    assert_eq!(idna::to_ascii(b""), b"xn--");
    assert_eq!(idna::to_ascii(b"ABC"), b"xn--abc");
    // No ACE detection: an already-prefixed input gets prefixed again.
    assert_eq!(idna::to_ascii(b"xn--a"), b"xn--xn--a");
    assert_eq!(idna::to_ascii(b"XN--A"), b"xn--xn--a");
}

#[test]
fn punycode_encode_prefixes_without_folding_case() {
    assert_eq!(idna::punycode_encode(b""), b"xn--");
    assert_eq!(idna::punycode_encode(b"ABC"), b"xn--ABC");
    assert_eq!(idna::punycode_encode(b"Example.COM"), b"xn--Example.COM");
}

#[test]
fn decoding_strips_one_lowercase_prefix_only() {
    for decode in [
        idna::to_unicode as fn(&[u8]) -> Vec<u8>,
        idna::punycode_decode as fn(&[u8]) -> Vec<u8>,
    ] {
        assert_eq!(decode(b"xn--a"), b"a");
        assert_eq!(decode(b"xn--"), b"");
        // Only one prefix comes off per call.
        assert_eq!(decode(b"xn--xn--a"), b"xn--a");
        // The match is case-sensitive and anchored at the start.
        assert_eq!(decode(b"XN--a"), b"XN--a");
        assert_eq!(decode(b"Xn--a"), b"Xn--a");
        assert_eq!(decode(b"axn--b"), b"axn--b");
        assert_eq!(decode(b"xn-a"), b"xn-a");
    }
}

#[test]
fn validators_use_byte_length_not_char_count() {
    assert!(!idna::is_valid_label(b""));
    assert!(idna::is_valid_label(&[b'a'; 63]));
    assert!(!idna::is_valid_label(&[b'a'; 64]));

    assert!(!idna::is_valid_domain(b""));
    assert!(idna::is_valid_domain(&[b'a'; 255]));
    assert!(!idna::is_valid_domain(&[b'a'; 256]));

    // 21 * 3 bytes = 63 -> valid label; 22 * 3 = 66 -> not, despite 22 chars.
    let cjk = "日".repeat(21).into_bytes();
    assert_eq!(cjk.len(), 63);
    assert!(idna::is_valid_label(&cjk));
    assert!(!idna::is_valid_label("日".repeat(22).as_bytes()));
}

#[test]
fn ascii_detection_is_a_high_bit_test() {
    assert!(idna::is_ascii_domain(b""));
    assert!(idna::is_ascii_domain(&[0x00, 0x41, 0x7f]));
    assert!(!idna::is_ascii_domain(&[0x80]));
    assert!(!idna::is_ascii_domain(&[0xff]));
    assert!(!idna::is_ascii_domain(&[b'a', 0x80, b'b']));

    // Field 8 is the exact negation of field 7 for every input.
    for input in [
        &b""[..], b"a", b"\x7f", b"\x80", b"\xff", b"caf\xc3\xa9", b"\xc3\x28",
    ] {
        assert_eq!(idna::is_idn_domain(input), !idna::is_ascii_domain(input));
    }
}

#[test]
fn case_folding_is_ascii_only() {
    assert_eq!(idna::to_lower(b"MiXeD"), b"mixed");
    // Latin-1 supplement, Greek sigma and a lone high byte are all untouched.
    assert_eq!(idna::to_lower("ÄÖÜ".as_bytes()), "ÄÖÜ".as_bytes());
    assert_eq!(idna::to_lower("Σ".as_bytes()), "Σ".as_bytes());
    assert_eq!(idna::to_lower(&[0x80, 0xff]), &[0x80, 0xff]);
    // Bytes adjacent to ASCII letters do not shift the fold.
    assert_eq!(idna::to_lower(b"\xffA\xff"), b"\xffa\xff");
}

/// `normalize` forwards to `to_lower`, so the two fields can never differ.
#[test]
fn normalize_equals_to_lower() {
    for input in [
        &b""[..], b"A", b"  spaced  ", b"a.B.", b"\t\n", b"\xc3\x84", b"XN--ABC",
    ] {
        assert_eq!(idna::normalize(input), idna::to_lower(input));
    }
}

#[test]
fn count_labels_counts_dots_plus_one() {
    assert_eq!(idna::count_labels(b""), 1);
    assert_eq!(idna::count_labels(b"a"), 1);
    assert_eq!(idna::count_labels(b"."), 2);
    assert_eq!(idna::count_labels(b".."), 3);
    assert_eq!(idna::count_labels(b"a.b"), 2);
    assert_eq!(idna::count_labels(b"a..b"), 3);
    assert_eq!(idna::count_labels(b".a."), 3);
    // A multi-byte ideographic full stop is not an ASCII dot.
    assert_eq!(idna::count_labels("。".as_bytes()), 1);
}

/// Builds the same line the driver prints, minus the trailing newline.
fn render(input: &[u8]) -> String {
    let fields: Vec<Vec<u8>> = vec![
        idna::to_ascii(input),
        idna::to_unicode(input),
        idna::punycode_encode(input),
        idna::punycode_decode(input),
        flag(idna::is_valid_domain(input)),
        flag(idna::is_valid_label(input)),
        flag(idna::is_ascii_domain(input)),
        flag(idna::is_idn_domain(input)),
        idna::to_lower(input),
        idna::normalize(input),
        idna::count_labels(input).to_string().into_bytes(),
    ];
    String::from_utf8(fields.join(&b' ')).expect("test inputs are valid UTF-8")
}

fn flag(value: bool) -> Vec<u8> {
    if value {
        b"1".to_vec()
    } else {
        b"0".to_vec()
    }
}

